package com.sumedha.commerce.product.entity; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="categories") public class Category{@Id @Column(name="category_id") private UUID id;private String name,slug,description;@Column(name="parent_category_id") private UUID parentCategoryId;private boolean active;@Column(name="created_at") private Instant createdAt;@Column(name="updated_at") private Instant updatedAt;protected Category(){}public Category(String n,String s,String d,UUID p){id=UUID.randomUUID();name=n;slug=s;description=d;parentCategoryId=p;active=true;createdAt=Instant.now();updatedAt=createdAt;}@PreUpdate void touch(){updatedAt=Instant.now();}public UUID getId(){return id;}public String getName(){return name;}public String getSlug(){return slug;}public String getDescription(){return description;}public UUID getParentCategoryId(){return parentCategoryId;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void update(String n,String s,String d,UUID p,boolean a){name=n;slug=s;description=d;parentCategoryId=p;active=a;}}
